user_prompt_template:
Analyze the following multi-timeframe technical data for {asset}.

Technical Features:
{macro_features}

Support/Resistance Levels:
{sr_levels}

Provide output in this exact JSON structure:
{
  "asset": "{asset}",
  "trend_alignment": {
    "direction": "bullish|bearish|mixed",
    "strength": "strong|moderate|weak",
    "timeframes_aligned": ["15m", "1h", "4h", "1d"],
    "detail": "trend analysis explanation"
  },
  "momentum_state": {
    "condition": "overbought|oversold|neutral",
    "divergence_detected": true|false,
    "detail": "momentum analysis explanation"
  },
  "volatility_state": {
    "level": "high|normal|low",
    "expanding": true|false,
    "detail": "volatility analysis explanation"
  },
  "key_levels": {
    "support": [float, float, ...],
    "resistance": [float, float, ...]
  },
  "structure_notes": "market structure observations",
  "disclaimer": "仅供参考，不构成投资建议"
}
